package top.monitorglobal.tv;
import android.app.AlertDialog;import android.graphics.Bitmap;import android.graphics.drawable.BitmapDrawable;import android.view.*;import android.widget.ImageView;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.lang.reflect.Field;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowAlertDialog;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import com.google.zxing.qrcode.QRCodeReader;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class DiagnosticDownloadUiTest {
 private ImageView image(View v){if(v instanceof ImageView&&((ImageView)v).getDrawable() instanceof BitmapDrawable)return (ImageView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){ImageView found=image(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 @Test public void qrDownloadsPreviousReportAndLeavingActivityClosesTheListener()throws Exception{
  android.content.Context c=RuntimeEnvironment.getApplication();RuntimeDiagnostics.stop();JSONObject report=new JSONObject().put("version","1.0.19").put("sampleCount",278).put("samples",new JSONArray().put(new JSONObject().put("at",123).put("pssKb",31948)));
  Files.write(RuntimeDiagnostics.previousFile(c).toPath(),report.toString().getBytes(StandardCharsets.UTF_8));
  ActivityController<DiagnosticsActivity> controller=Robolectric.buildActivity(DiagnosticsActivity.class).setup();DiagnosticsActivity activity=controller.get();LocalDiagnosticDownload server=null;
  try{activity.startDownload(true,InetAddress.getByName("127.0.0.1"));AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog);assertTrue(dialog.isShowing());ImageView qr=image(dialog.getWindow().getDecorView());assertNotNull(qr);Bitmap b=((BitmapDrawable)qr.getDrawable()).getBitmap();int[] pixels=new int[b.getWidth()*b.getHeight()];b.getPixels(pixels,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());String link=new QRCodeReader().decode(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(b.getWidth(),b.getHeight(),pixels)))).getText();
   Field field=DiagnosticsActivity.class.getDeclaredField("download");field.setAccessible(true);server=(LocalDiagnosticDownload)field.get(activity);assertEquals(server.url(),link);HttpURLConnection conn=(HttpURLConnection)new URL(link).openConnection();conn.setConnectTimeout(2000);conn.setReadTimeout(2000);try{assertEquals(200,conn.getResponseCode());assertTrue(conn.getHeaderField("Content-Disposition").contains("diagnostico-anterior.json"));JSONObject downloaded=new JSONObject(new String(conn.getInputStream().readAllBytes(),StandardCharsets.UTF_8));assertEquals(278,downloaded.getLong("sampleCount"));assertEquals("1.0.19",downloaded.getString("version"));}finally{conn.disconnect();}
   controller.pause().stop();assertFalse(dialog.isShowing());assertTrue(server.awaitStopped(2000));assertTrue(server.isClosed());assertNull(field.get(activity));
  }finally{if(server!=null)server.close();controller.destroy();RuntimeDiagnostics.previousFile(c).delete();}
 }
}
